#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
export BOOTSTRAP_REPO_ROOT="$SCRIPT_DIR"
export BOOTSTRAP_DRY_RUN=0
# shellcheck source=scripts/bootstrap/lib/common.sh
source "$SCRIPT_DIR/scripts/bootstrap/lib/common.sh"
# shellcheck source=scripts/bootstrap/lib/precheck.sh
source "$SCRIPT_DIR/scripts/bootstrap/lib/precheck.sh"
# shellcheck source=scripts/bootstrap/lib/apply.sh
source "$SCRIPT_DIR/scripts/bootstrap/lib/apply.sh"

ITEM_ID=()
ITEM_STOP=()
ITEM_LABEL=()
ITEM_STATUS=()
ITEM_DETAIL=()
ITEM_KIND=()
ITEM_ON=()
ITEM_LOCK=()
ITEM_SRC=()
ITEM_DST=()
MAC_STATUS=""
MAC_DETAIL=""
NET_STATUS=""
NET_DETAIL=""
BREW_BIN=""
BREW_FORMULAE=""
BREW_CASKS=""
BREW_OUTDATED=""
INSTALL_CHECK=0

reset_items() {
  ITEM_ID=()
  ITEM_STOP=()
  ITEM_LABEL=()
  ITEM_STATUS=()
  ITEM_DETAIL=()
  ITEM_KIND=()
  ITEM_ON=()
  ITEM_LOCK=()
  ITEM_SRC=()
  ITEM_DST=()
}

add_item() {
  ITEM_ID+=("$1")
  ITEM_STOP+=("$2")
  ITEM_LABEL+=("$3")
  ITEM_STATUS+=("$4")
  ITEM_DETAIL+=("$5")
  ITEM_KIND+=("$6")
  if [[ "$4" == "missing" ]]; then
    ITEM_ON+=(1)
  else
    ITEM_ON+=(0)
  fi
  ITEM_LOCK+=("")
  ITEM_SRC+=("${7:-}")
  ITEM_DST+=("${8:-}")
}

item_index() {
  local id="$1" i=0 n
  n=${#ITEM_ID[@]}
  while [[ $i -lt $n ]]; do
    if [[ "${ITEM_ID[$i]}" == "$id" ]]; then
      printf '%s' "$i"
      return 0
    fi
    i=$((i + 1))
  done
  return 1
}

item_on() {
  local i
  i=$(item_index "$1") || return 1
  [[ "${ITEM_ON[$i]}" == "1" ]]
}

item_lock() {
  local i
  if ! i=$(item_index "$1"); then
    printf ''
    return 0
  fi
  printf '%s' "${ITEM_LOCK[$i]}"
}

item_status() {
  local i
  i=$(item_index "$1") || return 1
  printf '%s' "${ITEM_STATUS[$i]}"
}

force_on() {
  local i
  if ! i=$(item_index "$1"); then
    warn "No row for $1."
    return 0
  fi
  ITEM_ON[$i]=1
  if [[ -z "${ITEM_LOCK[$i]}" ]]; then
    ITEM_LOCK[$i]="$2"
  fi
}

# A selected row forces the rows it needs. Turning the parent off clears the lock
# and leaves the dependency selected so it can be turned off on its own.
recompute_locks() {
  local i=0 n count=0 reason=""
  n=${#ITEM_ID[@]}
  while [[ $i -lt $n ]]; do
    ITEM_LOCK[$i]=""
    i=$((i + 1))
  done

  if item_on hammerspoon; then
    force_on blueutil "Hammerspoon"
  fi
  if item_on signing; then
    force_on gnupg "Commit signing"
    force_on pinentry-mac "Commit signing"
  fi

  i=0
  while [[ $i -lt $n ]]; do
    if [[ "${ITEM_STOP[$i]}" == "packages" && "${ITEM_ON[$i]}" == "1" ]]; then
      count=$((count + 1))
      reason="${ITEM_LABEL[$i]}"
    fi
    i=$((i + 1))
  done
  if [[ "$count" -eq 1 ]]; then
    force_on homebrew "$reason"
  elif [[ "$count" -gt 1 ]]; then
    force_on homebrew "selected packages"
  fi
}

hold() {
  if [[ "$INSTALL_CHECK" -eq 1 ]]; then
    return 0
  fi
  pause "${1:-Press Enter to continue}"
}

toggle_item() {
  local i="$1"
  if [[ -n "${ITEM_LOCK[$i]}" && "${ITEM_ON[$i]}" == "1" ]]; then
    if [[ "$INSTALL_CHECK" -eq 0 ]]; then
      warn "${ITEM_LABEL[$i]} stays selected because ${ITEM_LOCK[$i]} needs it."
      hold
    fi
    return 0
  fi
  if [[ "${ITEM_ON[$i]}" == "1" ]]; then
    ITEM_ON[$i]=0
  else
    ITEM_ON[$i]=1
  fi
  recompute_locks
}

toggle_id() {
  local i
  i=$(item_index "$1") || return 1
  toggle_item "$i"
}

toggle_stop() {
  local stop="$1" i=0 any=0 missing=0 restored=0
  while [[ $i -lt ${#ITEM_ID[@]} ]]; do
    if [[ "${ITEM_STOP[$i]}" == "$stop" && "${ITEM_ON[$i]}" == "1" ]]; then
      any=1
    fi
    i=$((i + 1))
  done

  if [[ "$any" == "1" ]]; then
    i=0
    while [[ $i -lt ${#ITEM_ID[@]} ]]; do
      if [[ "${ITEM_STOP[$i]}" == "$stop" ]]; then
        ITEM_ON[$i]=0
      fi
      i=$((i + 1))
    done
    recompute_locks
    i=0
    while [[ $i -lt ${#ITEM_ID[@]} ]]; do
      if [[ "${ITEM_STOP[$i]}" == "$stop" && "${ITEM_ON[$i]}" == "1" ]]; then
        if [[ "$INSTALL_CHECK" -eq 0 ]]; then
          warn "${ITEM_LABEL[$i]} stays selected because ${ITEM_LOCK[$i]} needs it."
        fi
        restored=1
      fi
      i=$((i + 1))
    done
    if [[ "$restored" -eq 1 ]]; then
      hold
    fi
    return 0
  fi

  i=0
  while [[ $i -lt ${#ITEM_ID[@]} ]]; do
    if [[ "${ITEM_STOP[$i]}" == "$stop" && "${ITEM_STATUS[$i]}" == "missing" ]]; then
      ITEM_ON[$i]=1
      missing=1
    fi
    i=$((i + 1))
  done
  if [[ "$missing" -eq 0 ]]; then
    warn "Nothing missing in this stop. Toggle a row to include it."
    hold
  fi
  recompute_locks
}

stop_has_selection() {
  local stop="$1" i=0
  while [[ $i -lt ${#ITEM_ID[@]} ]]; do
    if [[ "${ITEM_STOP[$i]}" == "$stop" && "${ITEM_ON[$i]}" == "1" ]]; then
      return 0
    fi
    i=$((i + 1))
  done
  return 1
}

stop_title() {
  case "$1" in
    preflight) printf 'Preflight' ;;
    shell) printf 'Shell' ;;
    packages) printf 'Packages' ;;
    symlinks) printf 'Symlinks' ;;
    hindsight) printf 'Hindsight' ;;
    signing) printf 'Commit signing' ;;
    *) printf '%s' "$1" ;;
  esac
}

selected_stop_count() {
  local n=0 stop
  for stop in preflight shell packages symlinks hindsight signing; do
    if stop_has_selection "$stop"; then
      n=$((n + 1))
    fi
  done
  printf '%s' "$n"
}

print_report() {
  local key=1 stop mark i n box extra
  say "Missing rows start selected. Matching, outdated, and different rows start unselected."
  for stop in preflight shell packages symlinks hindsight signing; do
    mark=" "
    if stop_has_selection "$stop"; then
      mark="x"
    fi
    say ""
    say "s${key} [${mark}] $(stop_title "$stop")"
    key=$((key + 1))
    if [[ "$stop" == "preflight" ]]; then
      note "macOS ${MAC_STATUS} ${MAC_DETAIL}"
      note "network ${NET_STATUS} ${NET_DETAIL}"
    fi
    i=0
    while [[ $i -lt ${#ITEM_ID[@]} ]]; do
      if [[ "${ITEM_STOP[$i]}" == "$stop" ]]; then
        n=$((i + 1))
        box=" "
        if [[ "${ITEM_ON[$i]}" == "1" ]]; then
          box="x"
        fi
        extra=""
        if [[ -n "${ITEM_LOCK[$i]}" ]]; then
          extra="kept by ${ITEM_LOCK[$i]}"
        fi
        if [[ -n "${ITEM_DETAIL[$i]}" ]]; then
          if [[ -n "$extra" ]]; then
            extra="${extra}; ${ITEM_DETAIL[$i]}"
          else
            extra="${ITEM_DETAIL[$i]}"
          fi
        fi
        say "$(printf '%2d [%s] %-28s %s' "$n" "$box" "${ITEM_LABEL[$i]}" "${ITEM_STATUS[$i]}")"
        if [[ -n "$extra" ]]; then
          note "    ${extra}"
        fi
      fi
      i=$((i + 1))
    done
  done
  say ""
  say "Number toggles a row. s1-s6 toggles a stop. Enter starts the install."
}

line_present() {
  local line="$1" file="$2"
  [[ -f "$file" ]] && grep -Fqx "$line" "$file"
}

first_matching_line() {
  local file="$1" mode="$2" line
  [[ -f "$file" ]] || return 1
  while IFS= read -r line || [[ -n "$line" ]]; do
    case "$mode" in
      shellenv)
        if [[ "$line" == *shellenv* ]]; then
          printf '%s' "$line"
          return 0
        fi
        ;;
      legacy)
        if [[ "$line" == *'/all.zsh"'* && "$line" != *'/cli/all.zsh"'* ]]; then
          printf '%s' "$line"
          return 0
        fi
        ;;
    esac
  done < "$file"
  return 1
}

remove_matching_lines() {
  local file="$1" mode="$2" tmp line
  [[ -f "$file" ]] || return 0
  tmp=$(mktemp)
  while IFS= read -r line || [[ -n "$line" ]]; do
    case "$mode" in
      shellenv)
        [[ "$line" == *shellenv* ]] && continue
        ;;
      legacy)
        if [[ "$line" == *'/all.zsh"'* && "$line" != *'/cli/all.zsh"'* ]]; then
          continue
        fi
        ;;
    esac
    printf '%s\n' "$line" >> "$tmp"
  done < "$file"
  mv "$tmp" "$file"
}

package_installed() {
  local kind="$1" name="$2" list
  if [[ "$kind" == "cask" ]]; then
    list="$BREW_CASKS"
  else
    list="$BREW_FORMULAE"
  fi
  printf '%s\n' "$list" | grep -Fxq "$name"
}

outdated_line() {
  local name="$1" line first
  while IFS= read -r line || [[ -n "$line" ]]; do
    [[ -z "$line" ]] && continue
    first="${line%% *}"
    if [[ "$first" == "$name" ]]; then
      printf '%s' "$line"
      return 0
    fi
  done <<< "$BREW_OUTDATED"
  return 1
}

node_24_present() {
  local prefix nvm_sh=""
  for prefix in /opt/homebrew /usr/local; do
    if [[ -s "$prefix/opt/nvm/nvm.sh" ]]; then
      nvm_sh="$prefix/opt/nvm/nvm.sh"
      break
    fi
  done
  [[ -n "$nvm_sh" ]] || return 1
  NVM_DIR="${NVM_DIR:-$HOME/.nvm}" bash -c 'source "$1"; nvm ls 24 >/dev/null 2>&1' _ "$nvm_sh"
}

rust_stable_present() {
  local prefix bin=""
  for prefix in /opt/homebrew /usr/local; do
    if [[ -x "$prefix/opt/rustup/bin/rustup" ]]; then
      bin="$prefix/opt/rustup/bin/rustup"
      break
    fi
  done
  if [[ -z "$bin" && -x "$HOME/.cargo/bin/rustup" ]]; then
    bin="$HOME/.cargo/bin/rustup"
  fi
  [[ -n "$bin" ]] || return 1
  "$bin" toolchain list 2>/dev/null | grep -q '^stable'
}

rustup_bin() {
  local prefix
  for prefix in /opt/homebrew /usr/local; do
    if [[ -x "$prefix/opt/rustup/bin/rustup" ]]; then
      printf '%s' "$prefix/opt/rustup/bin/rustup"
      return 0
    fi
  done
  if [[ -x "$HOME/.cargo/bin/rustup" ]]; then
    printf '%s' "$HOME/.cargo/bin/rustup"
    return 0
  fi
  return 1
}

add_package() {
  local kind="$1" name="$2" label="$3" status detail line
  detail=""
  if [[ -z "$BREW_BIN" ]] || ! package_installed "$kind" "$name"; then
    status="missing"
  else
    line=$(outdated_line "$name" || true)
    if [[ -n "$line" ]]; then
      status="outdated"
      detail="$line"
    else
      status="installed"
    fi
  fi
  if [[ "$name" == "nvm" && "$status" != "missing" ]] && ! node_24_present; then
    status="missing"
    detail="Node 24 is not installed"
  fi
  if [[ "$name" == "rustup" && "$status" != "missing" ]] && ! rust_stable_present; then
    status="missing"
    detail="stable toolchain is not installed"
  fi
  if [[ "$name" == "nvm" && "$status" == "missing" && -z "$detail" ]]; then
    detail="nvm and Node 24"
  fi
  if [[ "$name" == "rustup" && "$status" == "missing" && -z "$detail" ]]; then
    detail="rustup and the stable toolchain"
  fi
  add_item "$name" packages "$label" "$status" "$detail" "$kind"
}

add_link() {
  local id="$1" label="$2" src="$3" dst="$4" status detail
  detail=""
  if [[ -L "$dst" && "$(readlink "$dst")" == "$src" ]]; then
    status="installed"
  elif [[ ! -e "$dst" && ! -L "$dst" ]]; then
    status="missing"
  else
    status="different"
    if [[ -L "$dst" ]]; then
      detail="points at $(readlink "$dst")"
    elif [[ -d "$dst" ]]; then
      detail="directory at $dst"
    else
      detail="file at $dst"
    fi
  fi
  add_item "$id" symlinks "$label" "$status" "$detail" link "$src" "$dst"
}

build_survey() {
  local brew_bin want legacy spec config line name label cask_out
  reset_items

  if [[ "$(uname -s)" == "Darwin" ]]; then
    MAC_STATUS="installed"
    MAC_DETAIL="$(sw_vers -productVersion 2>/dev/null || true)"
  else
    MAC_STATUS="different"
    MAC_DETAIL="$(uname -s)"
  fi

  if ! command -v curl >/dev/null 2>&1; then
    NET_STATUS="missing"
    NET_DETAIL="curl not found"
  elif curl -fsSI --max-time 5 https://github.com >/dev/null 2>&1; then
    NET_STATUS="installed"
    NET_DETAIL="github.com answers"
  else
    NET_STATUS="missing"
    NET_DETAIL="cannot reach github.com"
  fi

  if xcode-select -p >/dev/null 2>&1; then
    add_item clt preflight "Command Line Tools" installed "" check
  else
    add_item clt preflight "Command Line Tools" missing "" check
  fi

  if brew_bin=$(bootstrap_find_brew_bin); then
    BREW_BIN="$brew_bin"
    add_item homebrew shell Homebrew installed "" brew
  else
    brew_bin="$(bootstrap_expected_brew_bin_for_arch)"
    add_item homebrew shell Homebrew missing "" brew
  fi

  printf -v want 'eval "$(%s shellenv)"' "$brew_bin"
  if line_present "$want" "$HOME/.zprofile"; then
    add_item shellenv shell "~/.zprofile shellenv" installed "" line
  elif legacy=$(first_matching_line "$HOME/.zprofile" shellenv); then
    add_item shellenv shell "~/.zprofile shellenv" different "$legacy" line
  else
    add_item shellenv shell "~/.zprofile shellenv" missing "" line
  fi

  printf -v want 'source "%s/cli/all.zsh"' "$BOOTSTRAP_REPO_ROOT"
  printf -v line 'source "%s/dev/hindsight.zsh"' "$BOOTSTRAP_REPO_ROOT"
  legacy=$(first_matching_line "$HOME/.zshrc" legacy || true)
  if line_present "$want" "$HOME/.zshrc" && line_present "$line" "$HOME/.zshrc"; then
    if [[ -n "$legacy" ]]; then
      add_item zshrc shell "~/.zshrc sources" different "legacy line: $legacy" line
    else
      add_item zshrc shell "~/.zshrc sources" installed "" line
    fi
  elif [[ -n "$legacy" ]]; then
    add_item zshrc shell "~/.zshrc sources" missing "legacy line: $legacy" line
  else
    add_item zshrc shell "~/.zshrc sources" missing "" line
  fi

  if [[ -n "$BREW_BIN" ]]; then
    BREW_FORMULAE=$("$BREW_BIN" list --formula 2>/dev/null || true)
    BREW_CASKS=$("$BREW_BIN" list --cask 2>/dev/null || true)
    BREW_OUTDATED=$("$BREW_BIN" outdated --formula --verbose 2>/dev/null || true)
    cask_out=$("$BREW_BIN" outdated --cask --verbose 2>/dev/null || true)
    BREW_OUTDATED="${BREW_OUTDATED}"$'\n'"${cask_out}"
  fi

  while IFS= read -r line || [[ -n "$line" ]]; do
    case "$line" in
      'brew "'*)
        name="${line#brew \"}"
        name="${name%%\"*}"
        label="$name"
        if [[ "$name" == "nvm" ]]; then
          label="Node (nvm + Node 24)"
        elif [[ "$name" == "rustup" ]]; then
          label="Rust (rustup + stable)"
        fi
        add_package formula "$name" "$label"
        ;;
      'cask "'*)
        name="${line#cask \"}"
        name="${name%%\"*}"
        add_package cask "$name" "$name"
        ;;
    esac
  done < "$BOOTSTRAP_REPO_ROOT/Brewfile"

  add_link ghostty Ghostty \
    "$BOOTSTRAP_REPO_ROOT/config/ghostty/config.ghostty" \
    "$HOME/Library/Application Support/com.mitchellh.ghostty/config.ghostty"
  add_link hammerspoon Hammerspoon \
    "$BOOTSTRAP_REPO_ROOT/config/hammerspoon" \
    "$HOME/.hammerspoon"
  add_link herdr Herdr \
    "$BOOTSTRAP_REPO_ROOT/config/herdr/config.toml" \
    "$HOME/.config/herdr/config.toml"

  config="$(bootstrap_hindsight_config_path)"
  if [[ -f "$config" ]]; then
    spec="$(head -n 1 "$config")"
    case "$spec" in
      op://*) spec="1Password reference" ;;
      env) spec="environment variable" ;;
      skip) spec="skip" ;;
      *) spec="unrecognized value" ;;
    esac
    add_item hindsight hindsight "key resolver" installed "$spec" human
  else
    add_item hindsight hindsight "key resolver" missing "" human
  fi

  if [[ -n "$(git config --global --get user.signingkey 2>/dev/null || true)" ]]; then
    add_item signing signing "gpg-signing.sh" installed "signing key is set" human
  else
    add_item signing signing "gpg-signing.sh" missing "" human
  fi

  recompute_locks
}

choose_rows() {
  local input n
  while true; do
    _clear
    printf '\n'
    print_report
    printf '  > '
    read -r input || true
    if [[ -z "$input" ]]; then
      return 0
    fi
    case "$input" in
      s1) toggle_stop preflight ;;
      s2) toggle_stop shell ;;
      s3) toggle_stop packages ;;
      s4) toggle_stop symlinks ;;
      s5) toggle_stop hindsight ;;
      s6) toggle_stop signing ;;
      *)
        if [[ "$input" =~ ^[0-9]+$ ]]; then
          n=$((10#$input))
          if [[ "$n" -ge 1 && "$n" -le ${#ITEM_ID[@]} ]]; then
            toggle_item $((n - 1))
          else
            warn "No row ${input}."
            hold
          fi
        else
          warn "Enter a row number, s1-s6, or press Enter to start."
          hold
        fi
        ;;
    esac
  done
}

explain_preflight() {
  say "Checks that this machine is macOS and that github.com answers."
  if [[ "$NET_STATUS" != "installed" ]]; then
    warn "Network: ${NET_DETAIL}. Installs may fail until that works."
  fi
  if item_on clt && [[ "$(item_status clt)" == "missing" ]]; then
    say "Command Line Tools are missing. You install them. This stop waits until they are present."
    step "Run: xcode-select --install"
    step "Finish the installer dialog, then return here."
  fi
}

explain_shell() {
  local idx
  if item_on homebrew; then
    say "Installs Homebrew when it is missing."
  fi
  if item_on shellenv; then
    say "Appends the Homebrew shellenv line to ~/.zprofile once."
    if [[ "$(item_status shellenv)" == "different" ]]; then
      idx=$(item_index shellenv)
      note "${ITEM_DETAIL[$idx]}"
      say "A different shellenv line stays unless you choose replace."
    fi
  fi
  if item_on zshrc; then
    say "Appends source lines for cli/all.zsh and dev/hindsight.zsh to ~/.zshrc once."
    idx=$(item_index zshrc)
    if [[ -n "${ITEM_DETAIL[$idx]}" ]]; then
      note "${ITEM_DETAIL[$idx]}"
      say "A legacy source all.zsh line stays unless you choose replace."
    fi
  fi
  say "The next shell sets mouse scaling to 9 and font smoothing to 0."
}

explain_packages() {
  local i=0 verb
  say "Installs each selected row. An outdated row is upgraded. Redo upgrades every selected row."
  while [[ $i -lt ${#ITEM_ID[@]} ]]; do
    if [[ "${ITEM_STOP[$i]}" == "packages" && "${ITEM_ON[$i]}" == "1" ]]; then
      verb="install"
      if [[ "${ITEM_STATUS[$i]}" == "outdated" ]]; then
        verb="upgrade"
      elif [[ "${ITEM_STATUS[$i]}" == "installed" ]]; then
        verb="leave"
      fi
      say "${verb} ${ITEM_LABEL[$i]}"
      if [[ -n "${ITEM_DETAIL[$i]}" ]]; then
        note "${ITEM_DETAIL[$i]}"
      fi
    fi
    i=$((i + 1))
  done
}

explain_symlinks() {
  local i=0
  say "Creates a symlink when the path is missing. A different path stays unless you choose replace."
  while [[ $i -lt ${#ITEM_ID[@]} ]]; do
    if [[ "${ITEM_STOP[$i]}" == "symlinks" && "${ITEM_ON[$i]}" == "1" ]]; then
      say "${ITEM_LABEL[$i]} → ${ITEM_DST[$i]}"
      if [[ "${ITEM_STATUS[$i]}" == "different" ]]; then
        note "${ITEM_DETAIL[$i]}"
      fi
    fi
    i=$((i + 1))
  done
  if item_on hammerspoon; then
    note "Hammerspoon keeps blueutil selected."
  fi
}

explain_hindsight() {
  local config idx
  config="$(bootstrap_hindsight_config_path)"
  say "Writes ${config} once, when that file is missing."
  say "Choices: a 1Password reference, the OPENAI_API_KEY already in the environment, or skip."
  note "Docker Desktop is a Packages row. This stop does not install it."
  if [[ "$(item_status hindsight)" == "installed" ]]; then
    idx=$(item_index hindsight)
    note "Already set (${ITEM_DETAIL[$idx]}). Continue leaves the file."
  fi
}

explain_signing() {
  say "Runs scripts/gpg-signing.sh."
  say "That script asks for your Git name, email, and signing key."
  say "It writes the global Git config and ~/.gnupg. Nothing is written into this repo."
  note "This stop keeps gnupg and pinentry-mac selected."
}

run_preflight() {
  bootstrap_run_precheck
  if item_on clt && ! xcode-select -p >/dev/null 2>&1; then
    while ! xcode-select -p >/dev/null 2>&1; do
      pause "Press Enter when the Command Line Tools install has finished."
    done
    say "Command Line Tools are installed."
  fi
}

run_shell() {
  local legacy idx
  if item_on homebrew; then
    bootstrap_install_homebrew_if_needed
  fi
  if item_on shellenv; then
    if [[ "$(item_status shellenv)" == "different" ]]; then
      if confirm "Replace the Homebrew shellenv line in ~/.zprofile?"; then
        remove_matching_lines "$HOME/.zprofile" shellenv
        bootstrap_configure_shellenv
        idx=$(item_index shellenv)
        ITEM_STATUS[$idx]="installed"
        ITEM_DETAIL[$idx]=""
      else
        say "Left the existing shellenv line in place."
      fi
    else
      bootstrap_configure_shellenv
    fi
  fi
  if item_on zshrc; then
    bootstrap_configure_zsh_source
    legacy=$(first_matching_line "$HOME/.zshrc" legacy || true)
    if [[ -n "$legacy" ]]; then
      note "Legacy line: ${legacy}"
      if confirm "Remove the legacy source all.zsh line from ~/.zshrc?"; then
        remove_matching_lines "$HOME/.zshrc" legacy
        say "Removed the legacy source line."
      else
        say "Left the legacy source line in place."
      fi
    fi
  fi
}

install_node_24() {
  local prefix nvm_sh=""
  for prefix in /opt/homebrew /usr/local; do
    if [[ -s "$prefix/opt/nvm/nvm.sh" ]]; then
      nvm_sh="$prefix/opt/nvm/nvm.sh"
      break
    fi
  done
  if [[ -z "$nvm_sh" ]]; then
    bootstrap_warn "nvm.sh not found. Node 24 was not installed."
    return 0
  fi
  bootstrap_log "Installing Node 24"
  NVM_DIR="${NVM_DIR:-$HOME/.nvm}" bash -c 'set -e; source "$1"; nvm install 24; nvm alias default 24' _ "$nvm_sh"
}

install_rust_stable() {
  local bin update="$1"
  bin=$(rustup_bin || true)
  if [[ -z "$bin" ]]; then
    bootstrap_warn "rustup not found. The stable toolchain was not installed."
    return 0
  fi
  if [[ "$update" -eq 1 ]]; then
    bootstrap_log "Updating Rust stable"
    bootstrap_run_cmd "$bin" update stable
  else
    bootstrap_log "Installing Rust stable"
    bootstrap_run_cmd "$bin" default stable
  fi
}

run_packages() {
  local redo="$1" i=0 brew_bin kind name
  PKG_INSTALL_FORMULA=()
  PKG_INSTALL_CASK=()
  PKG_UPGRADE_FORMULA=()
  PKG_UPGRADE_CASK=()

  while [[ $i -lt ${#ITEM_ID[@]} ]]; do
    if [[ "${ITEM_STOP[$i]}" == "packages" && "${ITEM_ON[$i]}" == "1" ]]; then
      kind="${ITEM_KIND[$i]}"
      name="${ITEM_ID[$i]}"
      if [[ "${ITEM_STATUS[$i]}" == "missing" ]]; then
        if [[ "$kind" == "cask" ]]; then
          PKG_INSTALL_CASK+=("$name")
        else
          PKG_INSTALL_FORMULA+=("$name")
        fi
      elif [[ "${ITEM_STATUS[$i]}" == "outdated" || "$redo" -eq 1 ]]; then
        if [[ "$kind" == "cask" ]]; then
          PKG_UPGRADE_CASK+=("$name")
        else
          PKG_UPGRADE_FORMULA+=("$name")
        fi
      fi
    fi
    i=$((i + 1))
  done

  if [[ ${#PKG_INSTALL_FORMULA[@]} -gt 0 || ${#PKG_INSTALL_CASK[@]} -gt 0 || ${#PKG_UPGRADE_FORMULA[@]} -gt 0 || ${#PKG_UPGRADE_CASK[@]} -gt 0 ]]; then
    if item_on homebrew; then
      bootstrap_install_homebrew_if_needed
    fi
    brew_bin="$(bootstrap_resolve_brew_bin)"
  fi

  if [[ ${#PKG_INSTALL_FORMULA[@]} -gt 0 ]]; then
    bootstrap_log "Installing ${PKG_INSTALL_FORMULA[*]}"
    bootstrap_run_cmd "$brew_bin" install "${PKG_INSTALL_FORMULA[@]}"
  fi
  if [[ ${#PKG_INSTALL_CASK[@]} -gt 0 ]]; then
    bootstrap_log "Installing ${PKG_INSTALL_CASK[*]}"
    bootstrap_run_cmd "$brew_bin" install --cask "${PKG_INSTALL_CASK[@]}"
  fi
  if [[ ${#PKG_UPGRADE_FORMULA[@]} -gt 0 ]]; then
    bootstrap_log "Upgrading ${PKG_UPGRADE_FORMULA[*]}"
    bootstrap_run_cmd "$brew_bin" upgrade "${PKG_UPGRADE_FORMULA[@]}"
  fi
  if [[ ${#PKG_UPGRADE_CASK[@]} -gt 0 ]]; then
    bootstrap_log "Upgrading ${PKG_UPGRADE_CASK[*]}"
    bootstrap_run_cmd "$brew_bin" upgrade --cask "${PKG_UPGRADE_CASK[@]}"
  fi

  if item_on nvm; then
    if [[ "$redo" -eq 1 ]] || ! node_24_present; then
      install_node_24
    fi
  fi
  if item_on rustup; then
    if [[ "$redo" -eq 1 ]] && rust_stable_present; then
      install_rust_stable 1
    elif ! rust_stable_present; then
      install_rust_stable 0
    fi
  fi
}

replace_path() {
  local dst="$1"
  if [[ -L "$dst" ]]; then
    rm "$dst"
  elif [[ -d "$dst" ]]; then
    rm -rf "$dst"
  else
    rm -f "$dst"
  fi
}

run_symlinks() {
  local i=0
  while [[ $i -lt ${#ITEM_ID[@]} ]]; do
    if [[ "${ITEM_STOP[$i]}" == "symlinks" && "${ITEM_ON[$i]}" == "1" ]]; then
      if [[ "${ITEM_STATUS[$i]}" == "different" ]]; then
        note "${ITEM_DETAIL[$i]}"
        if confirm "Replace ${ITEM_DST[$i]} with a symlink to this repo?"; then
          replace_path "${ITEM_DST[$i]}"
          bootstrap_link_when_missing "${ITEM_SRC[$i]}" "${ITEM_DST[$i]}" "${ITEM_LABEL[$i]}"
          ITEM_STATUS[$i]="installed"
          ITEM_DETAIL[$i]=""
        else
          say "Left ${ITEM_DST[$i]} in place."
        fi
      else
        bootstrap_link_when_missing "${ITEM_SRC[$i]}" "${ITEM_DST[$i]}" "${ITEM_LABEL[$i]}"
      fi
    fi
    i=$((i + 1))
  done
}

run_hindsight() {
  bootstrap_configure_hindsight
}

run_signing() {
  "$BOOTSTRAP_REPO_ROOT/scripts/gpg-signing.sh"
  pause "Signing script finished. Press Enter to return to the install."
}

run_stop() {
  case "$1" in
    preflight) run_preflight ;;
    shell) run_shell ;;
    packages) run_packages "$2" ;;
    symlinks) run_symlinks ;;
    hindsight) run_hindsight ;;
    signing) run_signing ;;
  esac
}

explain_stop() {
  case "$1" in
    preflight) explain_preflight ;;
    shell) explain_shell ;;
    packages) explain_packages ;;
    symlinks) explain_symlinks ;;
    hindsight) explain_hindsight ;;
    signing) explain_signing ;;
  esac
}

walk() {
  local stop reply title
  for stop in preflight shell packages symlinks hindsight signing; do
    if ! stop_has_selection "$stop"; then
      continue
    fi
    title=$(stop_title "$stop")
    stage "$title"
    explain_stop "$stop"
    while true; do
      printf '  continue, skip, redo, or abort? '
      read -r reply || true
      case "$reply" in
        continue)
          run_stop "$stop" 0
          break
          ;;
        skip)
          SKIPPED+=("${title} stop")
          break
          ;;
        redo)
          run_stop "$stop" 1
          ;;
        abort)
          say "Aborted."
          exit 0
          ;;
        *)
          warn "Type continue, skip, redo, or abort."
          ;;
      esac
    done
  done
}

on_state() {
  if item_on "$1"; then
    printf 1
  else
    printf 0
  fi
}

expect() {
  if [[ "$1" != "$2" ]]; then
    printf 'check failed: %s (got %q want %q)\n' "$3" "$1" "$2" >&2
    exit 1
  fi
}

selection_self_check() {
  INSTALL_CHECK=1
  reset_items
  add_item homebrew shell Homebrew installed "" brew
  add_item awscli packages awscli missing "" formula
  add_item blueutil packages blueutil installed "" formula
  add_item gnupg packages gnupg installed "" formula
  add_item pinentry-mac packages pinentry-mac installed "" formula
  add_item docker-desktop packages docker-desktop missing "" cask
  add_item hammerspoon symlinks Hammerspoon missing "" link
  add_item hindsight hindsight "key resolver" missing "" human
  add_item signing signing "gpg-signing.sh" missing "" human
  recompute_locks

  expect "$(on_state blueutil)" 1 "blueutil selected with Hammerspoon"
  expect "$(item_lock blueutil)" "Hammerspoon" "blueutil names Hammerspoon"
  expect "$(on_state gnupg)" 1 "gnupg selected with commit signing"
  expect "$(item_lock gnupg)" "Commit signing" "gnupg names commit signing"
  expect "$(item_lock pinentry-mac)" "Commit signing" "pinentry-mac names commit signing"
  expect "$(on_state docker-desktop)" 1 "missing docker starts selected"
  expect "$(item_lock docker-desktop)" "" "docker is not kept by Hindsight"
  expect "$(on_state hindsight)" 1 "hindsight stays selected"
  expect "$(item_lock homebrew)" "selected packages" "homebrew names selected packages"

  toggle_id gnupg
  expect "$(on_state gnupg)" 1 "gnupg stays on while commit signing is selected"

  toggle_id docker-desktop
  expect "$(on_state docker-desktop)" 0 "docker can be turned off"
  expect "$(item_lock docker-desktop)" "" "docker stays unlocked"
  expect "$(on_state hindsight)" 1 "hindsight does not follow docker"

  toggle_id blueutil
  expect "$(on_state blueutil)" 1 "blueutil stays on while Hammerspoon is selected"

  toggle_id hammerspoon
  expect "$(on_state hammerspoon)" 0 "Hammerspoon turns off"
  expect "$(on_state blueutil)" 1 "blueutil stays selected after unlock"
  expect "$(item_lock blueutil)" "" "blueutil lock clears"
  toggle_id blueutil
  expect "$(on_state blueutil)" 0 "unlocked blueutil can turn off"

  toggle_stop signing
  expect "$(on_state signing)" 0 "commit signing turns off"
  expect "$(on_state gnupg)" 1 "gnupg stays selected after unlock"
  expect "$(item_lock gnupg)" "" "gnupg lock clears"
  toggle_id gnupg
  toggle_id pinentry-mac
  expect "$(on_state gnupg)" 0 "unlocked gnupg can turn off"
  expect "$(on_state pinentry-mac)" 0 "unlocked pinentry-mac can turn off"

  expect "$(on_state awscli)" 1 "awscli still selected"
  expect "$(item_lock homebrew)" "awscli" "homebrew names the one package that needs it"
  toggle_id awscli
  expect "$(item_lock homebrew)" "" "homebrew unlocks when no package is selected"
  expect "$(on_state homebrew)" 1 "unlocked homebrew stays selected"

  printf 'selection check ok\n'
}

if [[ "${1:-}" == "--check" ]]; then
  selection_self_check
  exit 0
fi

build_survey
choose_rows
TOTAL_STAGES=$(selected_stop_count)
if [[ "$TOTAL_STAGES" -eq 0 ]]; then
  say "Nothing selected."
  exit 0
fi
banner "Install this machine"
_STAGE_INDEX=0
walk
finish
